import json,urllib.request,base64,os,sys
G="http://127.0.0.1:3000"; A="Basic "+base64.b64encode(("admin:"+os.environ["GP"]).encode()).decode()
def req(p,body=None):
    r=urllib.request.Request(G+p,data=json.dumps(body).encode() if body else None,headers={"Authorization":A,"Content-Type":"application/json"})
    return json.load(urllib.request.urlopen(r,timeout=60))
for uid in sys.argv[1:]:
    d=req("/api/dashboards/uid/"+uid)["dashboard"]
    panels=[]
    def walk(ps):
        for p in ps:
            if p.get("panels"): walk(p["panels"])
            if p.get("targets"): panels.append(p)
    walk(d.get("panels",[]))
    tot=0;nonempty=0;dss=set()
    for p in panels:
        for t in p["targets"]:
            ds=t.get("datasource") or p.get("datasource") or {}
            dss.add(json.dumps(ds) if isinstance(ds,dict) else ds)
            tt=dict(t); tt["datasource"]={"type":"influxdb","uid":"opentwins-influxdb"}; tt.setdefault("refId","A")
            try:
                res=req("/api/ds/query",{"from":"now-15m","to":"now","queries":[tt]})
                fr=list(res["results"].values())[0].get("frames",[])
                n=sum(len(f["data"]["values"][0]) if f.get("data",{}).get("values") else 0 for f in fr)
            except Exception as e: n=-1
            tot+=1; nonempty+= n>0
    print(uid,"panels",len(panels),"queries",tot,"with data",nonempty,"ds",dss)
EOF
